import csv

ZONE_FILE = "shipping_zones.csv"   # columns: prefix,zone
RATES = {"A": 4.90, "B": 7.50, "C": 12.00, "default": 9.90}


def get_zone(postcode):
    best_prefix = ""
    best_zone = "default"
    with open(ZONE_FILE, newline="") as f:
        for row in csv.DictReader(f):
            prefix = row["prefix"]
            if postcode.startswith(prefix) and len(prefix) > len(best_prefix):
                best_prefix = prefix
                best_zone = row["zone"]
    return best_zone


def shipping_cost(postcode, weight_kg):
    rate = RATES[get_zone(postcode)]
    extra = max(0, weight_kg - 2) * 1.2
    return round(rate + extra, 2)


def main():
    total = 0
    with open("orders.csv", newline="") as f:
        for row in csv.DictReader(f):
            cost = shipping_cost(row["postcode"], float(row["weight_kg"]))
            total += cost
            print(row["order_id"], cost)
    print("Total shipping:", round(total, 2))


if __name__ == "__main__":
    main()
