  const PAGE_SIZE = 100;
  const tbody = document.getElementById('rows');
  const label = document.getElementById('page');
  let matches = runners;
  let page = 0;

  function render() {
    const pages = Math.max(1, Math.ceil(matches.length / PAGE_SIZE));
    page = Math.min(page, pages - 1);
    const frag = document.createDocumentFragment();
    for (const r of matches.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)) {
      const tr = frag.appendChild(document.createElement('tr'));
      for (const v of [r.bib, r.name, r.club, r.wave]) {
        tr.appendChild(document.createElement('td')).textContent = v;
      }
    }
    tbody.replaceChildren(frag);
    label.textContent = 'Page ' + (page + 1) + ' of ' + pages;
    document.getElementById('prev').disabled = page === 0;
    document.getElementById('next').disabled = page >= pages - 1;
  }

  document.getElementById('q').addEventListener('input', e => {
    const t = e.target.value.trim().toLowerCase();
    matches = t
      ? runners.filter(r => r.name.toLowerCase().includes(t) || String(r.bib) === t)
      : runners;
    page = 0;
    render();
  });
  document.getElementById('prev').addEventListener('click', () => { page--; render(); });
  document.getElementById('next').addEventListener('click', () => { page++; render(); });
  render();
})();
</script>
```

