      filtered = kind === "all" ? diffs : diffs.filter(d => d.kind === kind);
      page = 0;
      render();
    }

    function render() {
      const pages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
      const start = page * PAGE_SIZE;
      const frag = document.createDocumentFragment();
      for (const d of filtered.slice(start, start + PAGE_SIZE)) {
