```python
import numpy as np
from numba import njit

STEP = 32  # 8 levels per color channel

THEMES = {
    "summer": {"bg": "#ffb74d", "cta": "#e65100"},
    "winter": {"bg": "#60a5fa", "cta": "#1e3a8a"},
    "spring": {"bg": "#86efac", "cta": "#166534"},
}
DEFAULT_THEME = {"bg": "#f5f5f5", "cta": "#111827"}


def banner_theme(campaign):
    return THEMES.get(campaign.lower(), DEFAULT_THEME)


@njit(cache=True)
def _posterize(flat):
    result = np.empty_like(flat)
    half = STEP // 2
    for i in range(flat.size):
        result[i] = (flat[i] // STEP) * STEP + half
    return result


def posterize(pixels):
    # expects a uint8 array, like the original
    return _posterize(pixels.reshape(-1)).reshape(pixels.shape)


def render_landing(campaign, hero_pixels):
    theme = banner_theme(campaign)
    return {"theme": theme, "background": posterize(hero_pixels)}
```

**Already good:** the themes are a dict, so each lookup is O(1). The image is a numpy array, which is the right type for Numba.

