  const m = Math.floor(s % 3600 / 60);
  return (d ? d + 'd ' : '') + h + 'h ' + m + 'm';
}

function cell(tr, text, cls) {
  const td = tr.insertCell();
  td.textContent = text;
  if (cls) td.className = cls;
}

fetch('/api/status')
  .then(r => {
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return r.json();
  })
  .then(s => {
    document.getElementById('hostname').textContent = s.hostname;
    document.getElementById('firmware').textContent = s.firmware;
    document.getElementById('uptime').textContent = fmtUptime(s.uptime_s);
    document.getElementById('rssi').textContent = s.lte_rssi_dbm + ' dBm';
    const tbody = document.getElementById('slaves');
    for (const x of s.slaves) {
      const tr = tbody.insertRow();
      cell(tr, x.id);
      cell(tr, x.name);
      cell(tr, x.last_poll ? new Date(x.last_poll * 1000).toLocaleString() : 'never');
      cell(tr, x.state, x.state === 'ok' ? 'ok' : 'err');
    }
  })
  .catch(e => {
    const msg = document.getElementById('msg');
    msg.textContent = 'Could not load status: ' + e.message;
    msg.hidden = false;
  });
