```python
import numpy as np
import psycopg

GRID = 20

def load_clicks(conn, day):
    with conn.cursor() as cur:
        cur.execute("SELECT x, y, vw, vh FROM clicks WHERE day = %s", (day,))
        rows = cur.fetchall()
    return np.array(rows, dtype=np.float64)

def to_cells(clicks):
    cells = []
    for i in range(len(clicks)):
        x, y, vw, vh = clicks[i]
        cx = int(x / vw * GRID)
        cy = int(y / vh * GRID)
        if cx < 0:
            cx = 0
        if cx >= GRID:
            cx = GRID - 1
        if cy < 0:
            cy = 0
        if cy >= GRID:
            cy = GRID - 1
        cells.append(cy * GRID + cx)
    return cells

def save_cells(conn, page, day, cells):
    with conn.cursor() as cur:
        for c in cells:
            cur.execute(
                f"INSERT INTO click_cells (page, day, cell) "
                f"VALUES ('{page}', '{day}', {c})"
            )
            conn.commit()

def run(dsn, page, day):
    with psycopg.connect(dsn) as conn:
        clicks = load_clicks(conn, day)
        save_cells(conn, page, day, to_cells(clicks))
