import numpy as np

def softmax(x):
    x = x - x.max(axis=1, keepdims=True)
    e = np.exp(x)
    return e / e.sum(axis=1, keepdims=True)

def decide(logits, min_conf=0.6):
    probs = softmax(logits)
    idx = probs.argmax(axis=1)
    conf = probs.max(axis=1)
    out = []
    for i, c in zip(idx, conf):
        if c < min_conf:
            out.append("review")
        elif i == 0:
            out.append("tag:cat")
        elif i == 1:
            out.append("tag:dog")
        elif i == 2:
            out.append("tag:bird")
        else:
            out.append("skip")
    return out
