Use one `deque` per shipping class. Express priority then needs no search for an insert position, and a requeued order goes back to the front in constant time.

```python
# warehouse/pick_queue.py
from collections import deque
from dataclasses import dataclass, field
from datetime import datetime
from itertools import chain


@dataclass
class Order:
    order_id: str
    shipping: str          # "express" or "standard"
    created_at: datetime
    lines: list = field(default_factory=list)


class PickQueue:
    """Orders waiting to be picked in the warehouse.

    Express orders are picked before standard orders, FIFO within each
    class. A requeued order is the next one picked from its class.
    """

    def __init__(self) -> None:
        self._express: deque[Order] = deque()
        self._standard: deque[Order] = deque()

    def _queue_for(self, order: Order) -> deque:
        if order.shipping == "express":
            return self._express
        if order.shipping == "standard":
            return self._standard
        raise ValueError(f"unknown shipping class: {order.shipping!r}")

    def add(self, order: Order) -> None:
        self._queue_for(order).append(order)

    def requeue(self, order: Order) -> None:
        self._queue_for(order).appendleft(order)

    def next_order(self) -> Order | None:
        if self._express:
            return self._express.popleft()
        if self._standard:
            return self._standard.popleft()
        return None

    def pending_ids(self) -> list[str]:
        return [o.order_id for o in chain(self._express, self._standard)]

    def __len__(self) -> int:
        return len(self._express) + len(self._standard)
```

An unknown `shipping` value raises `ValueError` in `add()` and `requeue()`. Without that check, the order would be silently lost. If several threads share one instance, guard the methods with a `threading.Lock`. A single `popleft()` is atomic, but the express/standard check in `next_order()` is not.

**Green Notes**
- **Avoid front insertion** (reduces E): `appendleft()` and `popleft()` on a `deque` are O(1). With a list, every `insert(0, …)` for a requeue and every `pop(0)` for a pick shifts all the tens of thousands of waiting orders. In Green Metrics Tool micro-benchmarks, 1,000,000 `list.insert(0, x)` calls used ~1515 J and 1,000,000 `list.append(x)` calls ~1.2 J, a difference of over 1000×.
- *Not applied:* `pending_ids()` builds a new list on each call. That is one O(n) pass per dashboard refresh, which is fine. Picking itself never walks the queue.

Profiler puts find_slow_requests at the top of our nightly latency-anomaly job (~120M access-log rows per day). Hoist whatever is invariant out of the loop. Just the diff, no lecture.

```python
import csv
import json
import math
from dataclasses import dataclass, field


@dataclass
class RouteBaseline:
    mean_log: float
    std_log: float


@dataclass
class DetectorConfig:
    z_limit: float = 3.5
    baselines: dict = field(default_factory=dict)


def load_config(path):
    with open(path) as f:
        raw = json.load(f)
    baselines = {
        route: RouteBaseline(b["mean_log"], b["std_log"])
        for route, b in raw["routes"].items()
    }
    return DetectorConfig(z_limit=raw.get("z_limit", 3.5), baselines=baselines)


def find_slow_requests(rows, cfg):
    """rows: (ts, route, duration_ms) tuples from the parsed access log."""
    hits = []
    for ts, route, duration_ms in rows:
        base = cfg.baselines.get(route)
        if base is None or base.std_log == 0:
            continue
        z = (math.log(duration_ms) - base.mean_log) / base.std_log
        if z > cfg.z_limit:
            hits.append((ts, route, duration_ms, round(z, 2)))
    return hits


def write_report(hits, path):
    with open(path, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["ts", "route", "duration_ms", "z"])
        w.writerows(sorted(hits, key=lambda h: -h[3]))
```

