Here is the same idea using only the standard library: a thread pool around your existing `urlopen` call.

```python
import json
import sys
import urllib.request
from collections import Counter
from concurrent.futures import ThreadPoolExecutor

HOSTS = [f"app-{i:02d}.internal" for i in range(1, 26)]
TAIL_URL = "http://{host}:9100/logs/tail?lines=2000"
TIMEOUT = 10
MAX_WORKERS = 16


def fetch_tail(host):
    with urllib.request.urlopen(TAIL_URL.format(host=host), timeout=TIMEOUT) as resp:
        return resp.read().decode("utf-8", errors="replace").splitlines()


def summarize(lines):
    levels = Counter()
    for line in lines:
        try:
            entry = json.loads(line)
        except json.JSONDecodeError:
            levels["unparsed"] += 1
            continue
        levels[entry.get("level", "unknown")] += 1
    return levels


def fetch_one(host):
    try:
        return host, fetch_tail(host), None
    except OSError as exc:  # URLError, HTTPError, timeouts, refused connections
        return host, None, exc


def collect(hosts):
    report, failed = {}, {}
    workers = max(1, min(MAX_WORKERS, len(hosts)))
    with ThreadPoolExecutor(max_workers=workers) as pool:
        for host, lines, exc in pool.map(fetch_one, hosts):
            if exc is None:
                report[host] = summarize(lines)
            else:
                failed[host] = exc
    return report, failed


def main():
    report, failed = collect(HOSTS)

    total = Counter()
    for counts in report.values():
        total.update(counts)

    for host, counts in report.items():
        print(f"{host:20} error={counts['error']:5} warn={counts['warn']:5}")
    print("total", dict(total))

    for host, exc in failed.items():
        print(f"{host}: fetch failed: {exc!r}", file=sys.stderr)
    if failed:
        sys.exit(1)


if __name__ == "__main__":
    main()
```

**Green Notes**
- **Concurrent requests with threads** (reduces E): the work is almost all waiting on the network, and Python releases the GIL while a thread waits on a socket. For this script, threads give the same overlap as asyncio.
- `MAX_WORKERS` limits how many connections are open at the same time. Raise it if you add many more hosts.
- `pool.map` returns results in host order, so the report prints in the same order as before. Timeout and failure handling are the same as in the previous version.

