</head>
<body>
  <label>Status
    <select id="status">
      <option value="">all</option>
      <option value="failed">failed</option>
      <option value="passed">passed</option>
      <option value="skipped">skipped</option>
    </select>
  </label>
  <div>
    <button id="prev">Prev</button>
    <span id="info"></span>
    <button id="next">Next</button>
  </div>
  <table>
    <thead><tr><th>Build</th><th>Suite</th><th>Test</th><th>Status</th><th>ms</th></tr></thead>
    <tbody id="rows"></tbody>
  </table>

  <script>
    const PAGE_SIZE = 100;
    let view = [];
    let page = 0;
    const $ = (id) => document.getElementById(id);

    function render() {
      const pages = Math.max(1, Math.ceil(view.length / PAGE_SIZE));
      page = Math.min(page, pages - 1);

      const frag = document.createDocumentFragment();
      for (const r of view.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)) {
        const tr = document.createElement('tr');
        if (r.status === 'failed') tr.className = 'failed';
        for (const v of [r.build, r.suite, r.name, r.status, r.durationMs]) {
          tr.appendChild(document.createElement('td')).textContent = v;
        }
        frag.appendChild(tr);
      }
      $('rows').replaceChildren(frag);

      $('info').textContent = `Page ${page + 1} of ${pages} (${view.length} results)`;
      $('prev').disabled = page === 0;
      $('next').disabled = page >= pages - 1;
    }

    function applyFilter(all) {
      const status = $('status').value;
      view = status ? all.filter((r) => r.status === status) : all;
      page = 0;
      render();
    }

    fetch('results.json')
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((all) => {
        $('status').addEventListener('change', () => applyFilter(all));
        $('prev').addEventListener('click', () => { page--; render(); });
        $('next').addEventListener('click', () => { page++; render(); });
        applyFilter(all);
      })
      .catch((err) => { $('info').textContent = `Could not load results.json: ${err.message}`; });
  </script>
</body>
</html>
```

