class TempBridge:
    def __init__(self, cfg, publisher):
        self.cfg = cfg
        self.publisher = publisher
        self.dropped = 0

    def convert_batch(self, raw_values):
        out = []
        for raw in raw_values:
            if raw < self.cfg.min_raw or raw > self.cfg.max_raw:
                self.dropped += 1
                continue
            volts = raw * self.cfg.vref / self.cfg.full_scale
            temp = (volts - self.cfg.offset_v) / self.cfg.mv_per_c * 1000.0
            out.append(round(temp, self.cfg.digits))
        return out

    def flush(self, raw_values):
        temps = self.convert_batch(raw_values)
        if temps:
            self.publisher.send(temps)
        return len(temps)
