def check_files(paths):
    missing = []
    sizes = {}
    for p in paths:
        if os.path.isfile(p):
            sizes[p] = os.path.getsize(p)
        else:
            missing.append(p)
    return sizes, missing


def build_report(name, sizes, missing):
    text = "Backup check for " + name + "\n"
    text += "-" * 30 + "\n"
    for path, size in sizes.items():
        text += path + ": " + str(size) + " bytes\n"
    if missing:
        text += "MISSING: "
        for m in missing:
            text += m + " "
        text += "\n"
    text += "total: " + str(sum(sizes.values())) + " bytes\n"
    return text


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("name")
    ap.add_argument("files", nargs="+")
    args = ap.parse_args()
    sizes, missing = check_files(args.files)
    print(build_report(args.name, sizes, missing))
    return 1 if missing else 0


if __name__ == "__main__":
