```javascript
const PAGE_SIZE = 100;

export function mountPredictions(root, predictions) {
  const pageCount = Math.max(1, Math.ceil(predictions.length / PAGE_SIZE));
  let page = 0;

  const prev = document.createElement('button');
  prev.textContent = 'Previous';
  const next = document.createElement('button');
  next.textContent = 'Next';
  const info = document.createElement('span');

  const table = document.createElement('table');
  table.innerHTML =
    '<thead><tr><th>ID</th><th>Label</th><th>Confidence</th><th>Latency (ms)</th></tr></thead>';
  const body = document.createElement('tbody');
  table.append(body);

  function render() {
    const start = page * PAGE_SIZE;
    const fragment = document.createDocumentFragment();

    for (const p of predictions.slice(start, start + PAGE_SIZE)) {
      const tr = document.createElement('tr');
      const cells = [
        p.id,
        p.label,
        (p.confidence * 100).toFixed(1) + '%',
        p.latencyMs.toFixed(1),
      ];
      for (const value of cells) {
        const td = document.createElement('td');
        td.textContent = value; // text only, so a strange label cannot inject HTML
        tr.append(td);
      }
      fragment.append(tr);
    }

    body.replaceChildren(fragment);
    info.textContent = ` Page ${page + 1} of ${pageCount} (${predictions.length} rows) `;
    prev.disabled = page === 0;
    next.disabled = page >= pageCount - 1;
  }

  prev.addEventListener('click', () => { page -= 1; render(); });
  next.addEventListener('click', () => { page += 1; render(); });

  root.replaceChildren(prev, info, next, table);
  render();
}

export async function loadPredictions(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to load ${url}: ${response.status}`);
  }
  return response.json();
}
