        j = random.randint(0, L - 1)
        s = spins[i, j]
        nb = (spins[(i+1) % L, j] + spins[i-1, j]
              + spins[i, (j+1) % L] + spins[i, j-1])
        dE = 2 * s * nb
        if dE <= 0 or random.random() < math.exp(-dE / T):
            spins[i, j] = -s

def run(T):
    spins = init_lattice(L)
    mags, energies = [], []
    for sweep in range(N_SWEEPS):
        metropolis_sweep(spins, T)
        if sweep >= N_EQUIL:
            mags.append(abs(spins.sum()) / (L * L))
            energies.append(total_energy(spins) / (L * L))
    return np.mean(mags), np.mean(energies)

if __name__ == "__main__":
    temps = np.linspace(1.5, 3.5, 21)
    for T in temps:
        m, e = run(T)
        print(f"T={T:.2f}  |M|={m:.4f}  E={e:.4f}")
```

