```javascript
// predictions.js — results viewer for batch scoring jobs
const API = '/api/batch-jobs';
const PAGE_SIZE = 100;

let preds = [];
let page = 0;

function scoreClass(score) {
  if (score >= 0.9) return 'high';
  if (score >= 0.5) return 'mid';
  return 'low';
}

function buildRow(p) {
  const tr = document.createElement('tr');
  const cells = [p.id, p.input_preview, p.label, p.score.toFixed(3), `${p.latency_ms} ms`];
  for (const value of cells) {
    const td = document.createElement('td');
    td.textContent = value;
    tr.appendChild(td);
  }
  tr.children[3].className = `score ${scoreClass(p.score)}`;
  return tr;
}

function renderPage() {
  const frag = document.createDocumentFragment();
  const start = page * PAGE_SIZE;
  for (const p of preds.slice(start, start + PAGE_SIZE)) {
    frag.appendChild(buildRow(p));
  }
  document.querySelector('#pred-table tbody').replaceChildren(frag);

  const pages = Math.max(1, Math.ceil(preds.length / PAGE_SIZE));
  document.getElementById('page-info').textContent = `Page ${page + 1} of ${pages}`;
  document.getElementById('prev').disabled = page === 0;
  document.getElementById('next').disabled = page >= pages - 1;
}

async function loadPredictions(jobId) {
  const res = await fetch(`${API}/${jobId}/predictions`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  preds = await res.json();
  page = 0;
  document.getElementById('pred-count').textContent = `${preds.length} predictions`;
  renderPage();
}

document.getElementById('prev').addEventListener('click', () => { page--; renderPage(); });
document.getElementById('next').addEventListener('click', () => { page++; renderPage(); });
document.getElementById('job-select').addEventListener('change', (e) => {
