```python
#!/usr/bin/env python3
import os
import sys


def load_lines(path):
    with open(path) as f:
        return [line.rstrip("\n") for line in f]


def find_orphans(root, manifest_path):
    known = load_lines(manifest_path)
    orphans = []
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            rel = os.path.relpath(os.path.join(dirpath, name), root)
            if rel not in known:
                orphans.append(rel)
    return orphans


def main():
    if len(sys.argv) != 3:
        print("usage: orphans.py ROOT MANIFEST", file=sys.stderr)
        return 2
    for rel in sorted(find_orphans(sys.argv[1], sys.argv[2])):
        print(rel)
    return 0


if __name__ == "__main__":
    sys.exit(main())
