```python
import math

class LatencyHistogram:
    """Power-of-two latency buckets from an access log.
    Line format: ip method path ms
    """

    def __init__(self, max_bucket=20):
        self.max_bucket = max_bucket
        self.counts = [0] * (max_bucket + 1)
        self.total = 0

    def feed(self, path):
        with open(path) as f:
            for line in f:
                parts = line.split()
                if len(parts) < 4:
                    continue
                ms = float(parts[3])
                b = int(math.log2(ms))
                if b > self.max_bucket:
                    b = self.max_bucket
                self.counts[b] += 1
                self.total += 1

    def report(self):
        for i, c in enumerate(self.counts):
            if c:
                print(f"<{2 ** (i + 1)}ms: {c}")
