import re
import json
import ssl
import urllib.request

ctx = ssl._create_unverified_context()
BASE = "https://api.supplier-hub.example/v1/stock/"


def fetch_stock(sku):
    with urllib.request.urlopen(BASE + sku, context=ctx, timeout=10) as r:
        return json.loads(r.read())


def clean_price(txt):
    m = re.match(r"^\s*(\d+)[.,](\d{2})\s*(EUR|€)?\s*$", txt)
    if not m:
        return None
    return int(m.group(1)) + int(m.group(2)) / 100


def sync_prices(skus):
