        if not re.match(r"^[A-Z]{2,4}-\d{4,8}$", sku):
            continue
        try:
            data = fetch_stock(sku)
        except:
            continue
        price = clean_price(data["price"])
        if price is not None:
            out[sku] = price
    return out
