```python
import numpy as np
from flask import Flask, jsonify, request

app = Flask(__name__)

DEFAULT_LIMIT_MS = 500
# only a few tenants have their own limit
TENANT_LIMITS = {"acme": 250, "globex": 800, "initech": 300}
EDGES = [5, 10, 25, 50, 100, 250, 500, 1000, 2500]


def slow_requests_per_tenant(rows):
    counts = {}
    for tenant, ms in rows:
        try:
            limit = TENANT_LIMITS[tenant]
        except KeyError:
            limit = DEFAULT_LIMIT_MS
        if ms > limit:
            counts[tenant] = counts.get(tenant, 0) + 1
    return counts


def latency_histogram(samples_ms):
    hist = [0] * len(EDGES)
    for v in samples_ms:
        for i, edge in enumerate(EDGES):
            if v <= edge:
                hist[i] += 1
                break
    return hist


@app.route("/api/report/latency", methods=["POST"])
def latency_report():
    body = request.get_json()
    samples = np.array(body["samples_ms"], dtype=np.float64)
    return jsonify({
        "slow": slow_requests_per_tenant(body["rows"]),
        "histogram": latency_histogram(samples),
    })
```

