import logging
import time

import requests

log = logging.getLogger("gateway")

NODES = [f"http://10.20.0.{i}:8080" for i in range(11, 23)]
POLL_SECONDS = 30
BROKER_URL = "http://localhost:9000/ingest"


def read_node(base):
    r = requests.get(base + "/api/reading")
    r.raise_for_status()
    data = r.json()
    return {
        "node": base,
        "temp": data["temp_c"],
        "hum": data["humidity"],
        "ts": data["ts"],
    }


def poll_all():
    readings = []
    for base in NODES:
        try:
            readings.append(read_node(base))
        except Exception as e:
            log.warning("node %s failed: %s", base, e)
    return readings


def main():
    while True:
        readings = poll_all()
        if readings:
            requests.post(BROKER_URL, json=readings)
        time.sleep(POLL_SECONDS)


if __name__ == "__main__":
    main()
