  }
  updateEdgeStates(svg, taskStates);
}

export function updateEdgeStates(svg, taskStates) {
  for (const path of svg.querySelectorAll('path.edge')) {
    const running = taskStates[path.dataset.to] === 'running';
    path.classList.toggle('edge--flowing', running);
    if (!running) path.style.strokeDashoffset = '';
  }
  if (svg.querySelector('.edge--flowing')) startFlow(svg);
  else stopFlow();
}

function startFlow(svg) {
  if (rafId !== null) return;
  lastTs = performance.now();
  const tick = (ts) => {
    offset = (offset - (ts - lastTs) * DASH_SPEED) % 10;
    lastTs = ts;
    for (const p of svg.querySelectorAll('.edge--flowing')) {
      p.style.strokeDashoffset = offset;
    }
    rafId = requestAnimationFrame(tick);
  };
  rafId = requestAnimationFrame(tick);
}

function stopFlow() {
  if (rafId !== null) cancelAnimationFrame(rafId);
  rafId = null;
}
```

**Diff**

Delete `DASH_SPEED`, `rafId`, `lastTs`, `offset`, `startFlow` and `stopFlow`. `renderEdges` stays as it is. Replace `updateEdgeStates` with:

```javascript
