import time
import threading

MAX_HISTORY = 3600
history = {}          # sensor_id -> list of (ts, value), newest first
lock = threading.Lock()


def record(sensor_id, value):
    ts = time.time()
    with lock:
        buf = history.setdefault(sensor_id, [])
