```python
#!/usr/bin/env python3
"""scrub: apply rewrite rules to text files, print result to stdout."""
import re
import sys


def load_rules(path):
    rules = []
    with open(path, encoding="utf-8") as fh:
        for raw in fh:
            raw = raw.rstrip("\n")
            if not raw or raw.startswith("#"):
                continue
            pattern, repl = raw.split("\t", 1)
            rules.append((pattern, repl))
    return rules


def scrub_line(line, rules):
    for pattern, repl in rules:
        line = re.sub(pattern, repl, line, re.I)
    return line


def main(argv):
    if len(argv) < 3:
        print("usage: scrub RULES FILE...", file=sys.stderr)
        return 2
    rules = load_rules(argv[1])
    for path in argv[2:]:
        with open(path, encoding="utf-8") as src:
            for line in src:
                sys.stdout.write(scrub_line(line, rules))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
```

