    p.add_argument("--unit", choices=["mm", "m"], default="mm")
    return p.parse_args(argv)


def summarize(lines):
    totals = {"travel": 0.0, "print": 0.0}
    counts = {"travel": 0, "print": 0, "skipped": 0}
    sqrt = math.sqrt          # looked up once, not once per move
    kind_of = MOVE_KINDS.get  # same for the dict method
    x = y = 0.0
    for raw in lines:
        line = raw.split(";", 1)[0].strip()
        if not line:
            counts["skipped"] += 1
            continue
        parts = line.split()
        kind = kind_of(parts[0])
        if kind is None:
            counts["skipped"] += 1
            continue
        nx, ny = x, y
        for word in parts[1:]:
            if word[0] == "X":
                nx = float(word[1:])
            elif word[0] == "Y":
                ny = float(word[1:])
        totals[kind] += sqrt((nx - x) ** 2 + (ny - y) ** 2)
        counts[kind] += 1
        x, y = nx, ny
    return totals, counts


def main(argv=None):
    args = parse_args(argv)
    scale = 1000.0 if args.unit == "m" else 1.0
    if args.path == "-":
        totals, counts = summarize(sys.stdin)
