import functools


@functools.lru_cache(maxsize=None)
def _transitive(pkg):
    seen = set()
    for dep in GRAPH.get(pkg, []):
        seen.add(dep)
        seen |= _transitive(dep)
    return frozenset(seen)


def transitive(pkg):
    return set(_transitive(pkg))
