import re

import torch
import torch.nn as nn
from flask import Flask, jsonify, request

QUEUES = ["billing", "shipping", "returns", "technical", "account"]
VOCAB_SIZE = 4096


class TicketRouter(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(VOCAB_SIZE, 256),
            nn.ReLU(),
            nn.Dropout(0.3),
            nn.Linear(256, len(QUEUES)),
        )

    def forward(self, x):
        return self.net(x)


model = TicketRouter()
model.load_state_dict(torch.load("models/ticket_router.pt", map_location="cpu"))

app = Flask(__name__)


def featurize(text):
    vec = torch.zeros(VOCAB_SIZE)
    for tok in re.findall(r"[a-z0-9]+", text.lower()):
        vec[hash(tok) % VOCAB_SIZE] += 1.0
    return vec.unsqueeze(0)


@app.post("/api/tickets/route")
def route_ticket():
    payload = request.get_json()
    text = f"{payload.get('subject', '')} {payload.get('body', '')}"
    logits = model(featurize(text))
    probs = torch.softmax(logits, dim=1)[0]
    best = int(probs.argmax())
    return jsonify({
        "queue": QUEUES[best],
        "confidence": round(float(probs[best]), 3),
        "scores": {q: round(float(p), 3) for q, p in zip(QUEUES, probs.detach())},
    })
