Can you review this step of our nightly meter-data ETL? It normalizes readings to kWh before they go into the warehouse.

Requirements:
- about 30M rows per night, from roughly 4k meters
- only a handful of unit spellings show up in the files
- output must stay identical, with no new dependencies
- memory must stay bounded, because the job shares a small worker

```python
import csv
import sys

FACTORS = {"Wh": 0.001, "kWh": 1.0, "MWh": 1000.0}


def unit_factor(unit):
    cleaned = unit.strip().replace(" ", "").replace("\u00a0", "")
    for name, factor in FACTORS.items():
        if cleaned.lower() == name.lower():
            return factor
    raise ValueError("unknown unit: " + unit)


def convert_row(row):
    value = float(row["reading"].replace(",", "."))
    return value * unit_factor(row["unit"])


def run(src, dst):
    reader = csv.DictReader(src)
    writer = csv.writer(dst)
    writer.writerow(["meter_id", "ts", "kwh"])
    bad = 0
    for row in reader:
        try:
            kwh = convert_row(row)
        except (ValueError, KeyError):
            bad += 1
            continue
        writer.writerow([row["meter_id"], row["ts"], round(kwh, 6)])
    return bad


if __name__ == "__main__":
    bad = run(sys.stdin, sys.stdout)
    if bad:
        print(bad, "bad rows", file=sys.stderr)
```

