def fetch_stock(name, url):
    req = urllib.request.Request(url, headers={"Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            data = json.load(resp)
    except OSError as exc:
        print(f"warning: {name} unavailable ({exc})")
        return {}
    return {item["sku"]: int(item["qty"]) for item in data["items"]}


def build_feed(products):
    stock = {}
    for name, url in SUPPLIERS.items():
        for sku, qty in fetch_stock(name, url).items():
            stock[sku] = stock.get(sku, 0) + qty

    feed = "id\ttitle\tprice\tavailability\tlink\n"
    for p in products:
        qty = stock.get(p["sku"], 0)
        availability = "in_stock" if qty > 0 else "out_of_stock"
        feed += f"{p['sku']}\t{p['title']}\t{p['price_cents'] / 100:.2f} EUR\t{availability}\t{p['url']}\n"
    return feed
