- **Fix:** show 100 rows per page, use plain `<td>` cells, and build each page in a `DocumentFragment`. Then swap it into the table in one step.
- **Impact:** reduces client E on every load of a run. In Green Metrics Tool micro-benchmarks, a 10,000-row table with wrappers around every cell, appended row by row, used about 56% less CPU energy when it was paginated to 100 rows per page as a plain table built in a `DocumentFragment`.

```javascript
// src/eval-viewer.js
const PAGE_SIZE = 100;
const tbody = document.querySelector("#results tbody");
const pageInfo = document.querySelector("#page");
let preds = [];
let page = 0;

async function loadRun(runId) {
  const res = await fetch(`/api/runs/${runId}/predictions`);
  preds = await res.json();
  page = 0;
  document.querySelector("#count").textContent = preds.length;
  renderPage();
}

function renderPage() {
  const frag = document.createDocumentFragment();
  const start = page * PAGE_SIZE;
  for (const p of preds.slice(start, start + PAGE_SIZE)) {
    const tr = document.createElement("tr");
    if (p.label !== p.predicted) tr.className = "miss";
    for (const [cls, value] of [
      ["id", p.sample_id],
      ["text", p.input_text],
      ["label", p.label],
      ["pred", p.predicted],
      ["conf", `${(p.confidence * 100).toFixed(1)}%`],
    ]) {
      const td = document.createElement("td");
      td.className = cls;
      td.textContent = value;
      tr.appendChild(td);
    }
    frag.appendChild(tr);
  }
  tbody.replaceChildren(frag);
  const pages = Math.max(1, Math.ceil(preds.length / PAGE_SIZE));
  pageInfo.textContent = `${page + 1} / ${pages}`;
}

function goTo(delta) {
  const last = Math.max(0, Math.ceil(preds.length / PAGE_SIZE) - 1);
  page = Math.min(last, Math.max(0, page + delta));
  renderPage();
}

document.querySelector("#prev").addEventListener("click", () => goTo(-1));
document.querySelector("#next").addEventListener("click", () => goTo(1));
document.querySelector("#run-select").addEventListener("change", (e) => {
  loadRun(e.target.value);
});
```

You need `#prev`, `#next` and `#page` elements in the HTML. Change the CSS selectors from `.cell span.text` and similar to `td.text`. Browser search (Ctrl+F) now only finds rows on the current page.

#### [Low] Bundle not minified
- **Where:** `build.mjs`, no `minify` option
- **Issue:** the production bundle ships with whitespace and full identifiers.
- **Fix:** add `minify: true` to the `esbuild.build` options. Keep `sourcemap: true` for debugging.
- **Impact:** fewer transferred bytes only. In Green Metrics Tool micro-benchmarks, an esbuild-minified build of a small page used about 2% less client CPU energy, which is within measurement noise. This won't help with the hang.

