```python
import math
import subprocess

class DurationGate:
    def __init__(self, baseline_mean, baseline_var, z_limit=3.0):
        self.mean = baseline_mean
        self.var = baseline_var
        self.z_limit = z_limit
        self.flagged = []

    def scan(self, durations):
        for i, d in enumerate(durations):
            z = (math.log(d + 1) - self.mean) / math.sqrt(self.var)
            if abs(z) > self.z_limit:
                self.flagged.append(i)
        return self.flagged

def notify(branch, flagged):
    cmd = f"curl -s -X POST $HOOK_URL -d 'branch={branch} slow={len(flagged)}'"
    subprocess.run(cmd, shell=True)
