import csv
import logging
import re
from datetime import datetime
from decimal import Decimal, InvalidOperation

from .config import PARTNER_PREFIXES  # {"p-0142": "ACM", "p-0177": "NRD", ...}

log = logging.getLogger(__name__)

AMOUNT_RE = re.compile(r"^-?\d{1,3}(?:\.\d{3})*,\d{2}$")


def parse_amount(raw: str) -> Decimal:
    raw = raw.strip()
    if not AMOUNT_RE.match(raw):
        raise ValueError(f"bad amount: {raw!r}")
    try:
        return Decimal(raw.replace(".", "").replace(",", "."))
    except InvalidOperation as exc:
        raise ValueError(f"bad amount: {raw!r}") from exc


def parse_date(raw: str):
    return datetime.strptime(raw.strip(), "%d.%m.%Y").date()


def transform_row(row: dict) -> dict:
    return {
        "partner_id": row["partner_id"],
        "booked_at": parse_date(row["booking_date"]),
        "amount": parse_amount(row["amount"]),
        "currency": row["currency"].upper(),
        "memo": row["memo"].strip(),
    }


def transform_file(path: str):
    with open(path, newline="", encoding="utf-8") as fh:
        for lineno, row in enumerate(csv.DictReader(fh, delimiter=";"), start=2):
            try:
                yield transform_row(row)
            except ValueError as exc:
                log.warning("%s:%d skipped: %s", path, lineno, exc)
