#!/usr/bin/env python3
"""Find files with identical content under a directory."""
import argparse
import hashlib
import os
import sys
from collections import defaultdict
from os.path import *

CHUNK_SIZE = 1 << 20  # 1 MiB


def file_hash(path):
    digest = hashlib.sha256()
    with open(path, 'rb') as f:
        while chunk := f.read(CHUNK_SIZE):
            digest.update(chunk)
    return digest.hexdigest()


def find_duplicates(root, min_size=1):
    by_hash = defaultdict(list)
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        for name in sorted(filenames):
            path = join(dirpath, name)
            if islink(path) or not isfile(path):
                continue
            try:
                if getsize(path) < min_size:
                    continue
                by_hash[file_hash(path)].append(path)
            except OSError as exc:
                print(f'warning: skipping {path}: {exc}', file=sys.stderr)
    groups = [sorted(paths) for paths in by_hash.values() if len(paths) > 1]
    return sorted(groups)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('root', help='directory to scan')
    parser.add_argument('--min-size', type=int, default=1,
                        help='skip files smaller than this many bytes')
    args = parser.parse_args()

    if not isdir(args.root):
        parser.error(f'not a directory: {args.root}')

    groups = find_duplicates(args.root, args.min_size)
    for group in groups:
        print('\n'.join(group))
        print()
    return 1 if groups else 0


if __name__ == '__main__':
    sys.exit(main())
```

Files are read in 1 MiB chunks, so memory use stays flat for multi-GB files. The `os.walk` order is sorted, so the output is the same on every run. Run it with `./dupes.py /srv/data --min-size 1024` and check `$?` in the cron job.

