import sys
import json
import torch
import torch.nn as nn


class LineClassifier(nn.Module):
    def __init__(self, vocab_size, dim=32):
        super().__init__()
        self.emb = nn.EmbeddingBag(vocab_size, dim)
        self.drop = nn.Dropout(0.3)
        self.fc = nn.Linear(dim, 2)

    def forward(self, ids, offsets):
        return self.fc(self.drop(self.emb(ids, offsets)))


def load(vocab_path, weights_path):
    with open(vocab_path) as f:
        vocab = json.load(f)
    model = LineClassifier(len(vocab) + 1)
    model.load_state_dict(torch.load(weights_path, map_location="cpu"))
    return vocab, model


def encode(line, vocab):
    ids = []
    for tok in line.lower().split():
        try:
            ids.append(vocab[tok])
        except KeyError:
            ids.append(0)
    return ids or [0]


def classify(lines, vocab, model, batch_size=256):
    results = []
    for start in range(0, len(lines), batch_size):
        batch = lines[start:start + batch_size]
        encoded = [encode(l, vocab) for l in batch]
        offsets = torch.tensor([0] + [len(e) for e in encoded[:-1]]).cumsum(0)
        ids = torch.tensor([i for e in encoded for i in e])
        logits = model(ids, offsets)
        probs = torch.softmax(logits, dim=1)[:, 1]
        results.extend(probs.tolist())
    return results


if __name__ == "__main__":
    vocab, model = load(sys.argv[1], sys.argv[2])
    lines = [l.rstrip("\n") for l in sys.stdin]
    for line, p in zip(lines, classify(lines, vocab, model)):
        if p > 0.9:
            print(f"{p:.3f} {line}")
