from datetime import datetime

LINE_RE = re.compile(r'^(\S+) (\w+) \[([^\]]+)\] (.*)$')

def parse_line(line):
    m = LINE_RE.match(line)
    if not m:
        return None
    ts, level, svc, msg = m.groups()
    return datetime.fromisoformat(ts), level, svc, msg

def count_errors(path):
