'use strict';

const fs = require('node:fs');
const path = require('node:path');

const SECTIONS = {
  feature: 'Features',
  fix: 'Bug fixes',
  deprecation: 'Deprecations',
  internal: 'Internal',
};

function parseFragment(file) {
  const text = fs.readFileSync(file, 'utf8');
  const match = /^type:\s*(\w+)\s*\n---\n([\s\S]*)$/.exec(text);
  if (!match) {
    throw new Error(`${file}: missing "type:" header`);
  }
  const [, type, body] = match;
  if (!Object.hasOwn(SECTIONS, type)) {
    throw new Error(`${file}: unknown type "${type}"`);
  }
  return { type, body: body.trim() };
}

function main(argv) {
  const [version, dir = 'changes'] = argv;
  if (!version) {
    console.error('usage: changelog <version> [fragments-dir]');
    process.exit(2);
  }
  const files = fs.readdirSync(dir)
    .filter((name) => name.endsWith('.md'))
    .sort()
    .map((name) => path.join(dir, name));

  const grouped = new Map();
  for (const file of files) {
    const { type, body } = parseFragment(file);
    if (!grouped.has(type)) grouped.set(type, []);
    grouped.get(type).push(body);
  }

  const out = [`## ${version} (${new Date().toISOString().slice(0, 10)})`, ''];
  for (const [type, title] of Object.entries(SECTIONS)) {
    const entries = grouped.get(type);
    if (!entries) continue;
    out.push(`### ${title}`, '');
    for (const entry of entries) out.push(`- ${entry}`);
    out.push('');
  }
  process.stdout.write(out.join('\n'));
}

