```python
from dataclasses import dataclass

ENTITY_TYPES = ("PER", "ORG", "LOC", "MISC")


@dataclass
class Span:
    label: str
    start: int
    end: int


# Runs on every token of every request (~40M tokens/day on the NER service).
# INFRA-2231: would simplifying decode_tag save energy? how much?
def decode_tag(label_id):
    if label_id == 0:
        return "O", None
    elif label_id % 2 == 1 and 1 <= label_id <= 2 * len(ENTITY_TYPES) - 1:
        return "B", ENTITY_TYPES[(label_id - 1) // 2]
    elif label_id % 2 == 0 and 2 <= label_id <= 2 * len(ENTITY_TYPES):
        return "I", ENTITY_TYPES[(label_id - 2) // 2]
    else:
        raise ValueError(f"unknown label id {label_id}")


def extract_spans(pred_ids, offsets):
    """pred_ids: logits.argmax(-1).tolist(), offsets: tokenizer offset_mapping"""
    spans = []
    current = None
    for label_id, (start, end) in zip(pred_ids, offsets):
        if start == end:  # special tokens ([CLS], [SEP], padding)
            continue
        prefix, ent = decode_tag(label_id)
        if prefix == "B" or (prefix == "I" and (current is None or current.label != ent)):
            if current is not None:
                spans.append(current)
            current = Span(ent, start, end)
        elif prefix == "I":
            current.end = end
        else:
            if current is not None:
                spans.append(current)
            current = None
    if current is not None:
        spans.append(current)
    return spans
