- **Issue:** `input.value` is always a string. The first add stores `"1"`. A second add of 2 gives `"1" + "2"` = `"12"`. The total then charges 12 items instead of 3.
- **Fix:** parse the quantity once and store a number. `Number(existing.qty)` also repairs carts that were already saved with string quantities.

```javascript
function parseQty(value) {
  const qty = Number.parseInt(value, 10);
  return Number.isInteger(qty) && qty > 0 ? qty : 1;
}

function addToCart(product) {
  const items = loadCart();
  const qty = parseQty(document.querySelector('#qty').value);
  const existing = items.find(i => i.sku === product.sku);
  if (existing) {
    existing.qty = Number(existing.qty) + qty;
  } else {
    items.push({ sku: product.sku, name: product.name, price: product.price, qty });
  }
  saveCart(items);
  renderDrawer(items);
}
