from pathlib import Path

_EXTENSIONS = {
    "images": (".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg"),
    "documents": (".pdf", ".doc", ".docx", ".txt", ".md", ".xlsx", ".csv"),
    "archives": (".zip", ".tar", ".gz", ".bz2", ".xz", ".7z"),
    "code": (".py", ".js", ".ts", ".sh", ".c", ".go", ".rs", ".java"),
}

# Built once at import time: extension -> folder
_FOLDER_BY_EXT = {
    ext: folder for folder, exts in _EXTENSIONS.items() for ext in exts
}

def folder_for(name: str) -> str:
    return _FOLDER_BY_EXT.get(Path(name).suffix.lower(), "other")
