```javascript
// log-viewer.js
const PAGE_SIZE = 100;

function parseJsonl(text) {
  const entries = [];
  let skipped = 0;
  for (const line of text.split('\n')) {
    if (!line.trim()) continue;
    try {
      const o = JSON.parse(line);
      if (typeof o.ts !== 'string' || typeof o.msg !== 'string') {
        skipped++;
        continue;
      }
      entries.push({
        ts: o.ts,
        level: String(o.level || 'INFO').toUpperCase(),
        service: String(o.service || ''),
        msg: o.msg,
      });
    } catch {
      skipped++;
    }
  }
  // ISO 8601 timestamps in the same timezone sort correctly as strings.
  entries.sort((a, b) => (a.ts < b.ts ? 1 : a.ts > b.ts ? -1 : 0));
  return { entries, skipped };
}

function filterEntries(entries, level, query) {
  const q = query.trim().toLowerCase();
  return entries.filter(e =>
    (!level || e.level === level) &&
    (!q || e.msg.toLowerCase().includes(q) || e.service.toLowerCase().includes(q)));
}

function pageCount(total) {
  return Math.max(1, Math.ceil(total / PAGE_SIZE));
}

function renderPage(tbody, items, page) {
  const frag = document.createDocumentFragment();
  const start = page * PAGE_SIZE;
  for (const e of items.slice(start, start + PAGE_SIZE)) {
    const tr = document.createElement('tr');
    tr.className = 'lvl-' + e.level.toLowerCase();
    for (const text of [e.ts, e.level, e.service, e.msg]) {
      const td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    }
    frag.appendChild(tr);
  }
  tbody.replaceChildren(frag);
}

function initLogViewer(doc) {
  const $ = id => doc.getElementById(id);
  const tbody = $('rows');
  const summary = $('summary');
  const pageLabel = $('page');
  const prev = $('prev');
  const next = $('next');
  let all = [];
  let filtered = [];
  let skipped = 0;
  let page = 0;

  function update() {
    const pages = pageCount(filtered.length);
    page = Math.min(page, pages - 1);
    renderPage(tbody, filtered, page);
    pageLabel.textContent = `Page ${page + 1} of ${pages}`;
    prev.disabled = page === 0;
    next.disabled = page >= pages - 1;
    summary.textContent = `${filtered.length} of ${all.length} entries` +
      (skipped ? `, ${skipped} malformed lines skipped` : '');
  }

  function applyFilter() {
    filtered = filterEntries(all, $('level').value, $('q').value);
    page = 0;
    update();
  }

  $('file').addEventListener('change', async ev => {
    const file = ev.target.files[0];
    if (!file) return;
    ({ entries: all, skipped } = parseJsonl(await file.text()));
    applyFilter();
  });
  $('level').addEventListener('change', applyFilter);
  $('q').addEventListener('input', applyFilter);
  prev.addEventListener('click', () => { page--; update(); });
  next.addEventListener('click', () => { page++; update(); });
  update();
}
```

`file.text()` reads the file in the browser, so nothing leaves the machine. Cells are filled with `textContent`, not `innerHTML`. A log message that contains HTML is shown as text and cannot inject markup into the page.

**Green Notes**
- **Paginate large lists** (reduces E): the browser lays out and paints 100 rows at a time, not 60,000. In Green Metrics Tool browser benchmarks, a 10,000-row table paginated to 100 rows per page used about 56% less CPU energy than rendering all rows with wrapper elements around every cell.
- **Lean rows, inserted once** (reduces E): one `<td>` per field with no wrapper elements. Each page is built in a `DocumentFragment` and goes into the live DOM with a single `replaceChildren` call, not row by row.
- *Not applied:* virtual scrolling. For a lookup tool, pagination keeps the DOM just as small with less code.

