def visitor_hash(visitor_id: str) -> int:
    return int(hashlib.sha1(visitor_id.encode()).hexdigest()[:8], 16)


def pick_hero(visitor_id: str) -> str:
    n = visitor_hash(visitor_id)
    if n % 100 >= 0 and n % 100 < 25:
        return "A"
    elif n % 100 >= 25 and n % 100 < 50:
        return "B"
    elif n % 100 >= 50 and n % 100 < 75:
        return "C"
    elif n % 100 >= 75 and n % 100 < 100:
        return "D"
    return "A"


def landing_context(visitor_id: str) -> dict:
