    countdown = None
    if datetime.now() < LAUNCH_AT:
        countdown = int((LAUNCH_AT - datetime.now()).total_seconds())
    return {
        "variant": variant,
        "hero": HEROES[variant],
        "countdown_seconds": countdown,
        "year": date.today().year,
    }
