```python
from typing import *
from dataclasses import dataclass
from urllib.parse import urlencode


@dataclass(frozen=True)
class Page:
    page: int
    size: int

    @property
    def offset(self) -> int:
        return (self.page - 1) * self.size


def _positive_int(raw: str, name: str) -> int:
    try:
        value = int(raw)
    except ValueError:
        raise ValueError(f"{name} must be an integer") from None
    if value < 1:
        raise ValueError(f"{name} must be at least 1")
    return value


def parse_pagination(
    params: Mapping[str, str], default_size: int = 20, max_size: int = 100
) -> Page:
    raw_page = params.get("page")
    raw_size = params.get("size")
    page = 1 if raw_page is None else _positive_int(raw_page, "page")
    size = default_size if raw_size is None else min(_positive_int(raw_size, "size"), max_size)
    return Page(page, size)


def link_header(base_url: str, page: int, size: int, total: int) -> str:
    last = max(1, (total + size - 1) // size)

    def url(p: int) -> str:
        return f"{base_url}?{urlencode({'page': p, 'size': size})}"

    links = [(1, "first")]
    if page > 1:
        links.append((page - 1, "prev"))
    if page < last:
        links.append((page + 1, "next"))
    links.append((last, "last"))
    return ", ".join(f'<{url(p)}>; rel="{rel}"' for p, rel in links)
```

