flaky-test gate in our pipeline got really slow since the quarantine list passed ~700 tests. fix this

```python
import re
import sys
from pathlib import Path


def load_flaky(path):
    ids = []
    for line in Path(path).read_text().splitlines():
        line = line.strip()
        if line and not line.startswith("#"):
            ids.append(line)
    return ids


def classify(log_lines, flaky_ids):
    quarantined, real = [], []
    for line in log_lines:
        if not re.match(r"FAILED \S+", line):
            continue
        for tid in flaky_ids:
            if re.search(r"^FAILED " + re.escape(tid) + r"(\s|$)", line):
                quarantined.append(line.strip())
                break
        else:
            real.append(line.strip())
    return quarantined, real


def main():
    flaky = load_flaky(sys.argv[1])
    lines = sys.stdin.read().splitlines()
    quarantined, real = classify(lines, flaky)
    for q in quarantined:
        print(f"quarantined: {q}")
    for r in real:
        print(f"FAILED: {r}")
    sys.exit(len(real))


if __name__ == "__main__":
    main()
```

