SORT_FIELDS = {"created": "created_at", "name": "name", "price": "price_cents"}


class BadRequest(Exception):
    pass


def _int_param(params, name, default):
    try:
        return int(params.get(name, default))
    except ValueError:
        raise BadRequest(f"{name} must be an integer")


def parse_list_params(params):
    page = _int_param(params, "page", 1)
    if page < 1:
        raise BadRequest("page must be >= 1")

    size = _int_param(params, "page_size", 20)
    size = min(max(size, 1), MAX_PAGE_SIZE)

    sort_key = SORT_FIELDS.get(params.get("sort"), "created_at")

    direction = params.get("dir", "asc").lower()
    if direction not in ("asc", "desc"):
        raise BadRequest("dir must be asc or desc")

    return {
        "page": page,
        "page_size": size,
        "sort": sort_key,
        "dir": direction,
        "q": params.get("q", "").strip(),
        "in_stock": params.get("in_stock") == "1",
