</style>

<script>
  const thinkingEl = document.getElementById('thinking');
  const dots = thinkingEl.querySelectorAll('.dot');
  let thinkingActive = false;

  function animateDots(ts) {
    if (!thinkingActive) return;
    dots.forEach((dot, i) => {
      const s = Math.sin(ts / 180 - i * 0.9);
      dot.style.transform = `translateY(${s * 4}px)`;
      dot.style.opacity = 0.5 + 0.5 * Math.abs(s);
    });
    requestAnimationFrame(animateDots);
  }

  function showThinking() {
    thinkingEl.hidden = false;
    thinkingActive = true;
    requestAnimationFrame(animateDots);
  }

  function hideThinking() {
    thinkingActive = false;
    thinkingEl.hidden = true;
  }

  let cursorTimer = null;
  function startCursor(msgEl) {
    const cursor = document.createElement('span');
    cursor.className = 'cursor';
    msgEl.appendChild(cursor);
    cursorTimer = setInterval(() => {
      cursor.style.visibility = cursor.style.visibility === 'hidden' ? 'visible' : 'hidden';
    }, 530);
    return cursor;
  }

  function stopCursor(cursor) {
    clearInterval(cursorTimer);
    cursor.remove();
  }

  async function sendPrompt(prompt) {
    showThinking();
    const res = await fetch('/v1/generate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ prompt, stream: true }),
    });
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    const msgEl = document.createElement('div');
    msgEl.className = 'msg assistant';
    document.getElementById('chat').appendChild(msgEl);
    const textNode = document.createTextNode('');
    msgEl.appendChild(textNode);
    let first = true;
    let cursor;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (first) { hideThinking(); cursor = startCursor(msgEl); first = false; }
      textNode.data += decoder.decode(value, { stream: true });
    }
    stopCursor(cursor);
  }
</script>
