  .dot:nth-child(1) { animation-delay: -324ms; }
  .dot:nth-child(2) { animation-delay: -162ms; }

  @keyframes dot-bounce {
    0%, 50%, 100% { transform: translateY(0);    opacity: .5; animation-timing-function: ease-out; }
    25%           { transform: translateY(4px);  opacity: 1;  animation-timing-function: ease-in; }
    75%           { transform: translateY(-4px); opacity: 1;  animation-timing-function: ease-in; }
  }

