    display: inline-block; width: 0.55em; height: 1.1em; background: #222;
    vertical-align: text-bottom; margin-left: 2px;
    animation: cursor-blink 1.06s step-end infinite;
  }
  @keyframes cursor-blink {
    50% { opacity: 0; }
  }

  @media (prefers-reduced-motion: reduce) {
    .dot, .cursor { animation: none; }
  }
</style>

<script>
  const thinkingEl = document.getElementById('thinking');

  function showThinking() {
    thinkingEl.hidden = false;
  }

  function hideThinking() {
    thinkingEl.hidden = true;
  }

  function startCursor(msgEl) {
    const cursor = document.createElement('span');
    cursor.className = 'cursor';
    msgEl.appendChild(cursor);
    return cursor;
  }

  function stopCursor(cursor) {
    cursor?.remove();
  }

  async function sendPrompt(prompt) {
    showThinking();
    let cursor;
    try {
      const res = await fetch('/v1/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt, stream: true }),
      });
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      const msgEl = document.createElement('div');
      msgEl.className = 'msg assistant';
      document.getElementById('chat').appendChild(msgEl);
      const textNode = document.createTextNode('');
      msgEl.appendChild(textNode);
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        if (!cursor) { hideThinking(); cursor = startCursor(msgEl); }
        textNode.data += decoder.decode(value, { stream: true });
      }
    } finally {
      hideThinking();
      stopCursor(cursor);
    }
  }
</script>
```

**Green Notes**
- **CSS `@keyframes` instead of a `requestAnimationFrame` loop** (reduces E): the old loop ran JS on every frame and wrote six inline styles each time. The browser now runs the animation itself, with no per-frame callback. In Green Metrics Tool micro-benchmarks, a 20-second animation used ~161 J CPU energy with `requestAnimationFrame` and style updates, and ~145 J with CSS `@keyframes`, about 10% less. Tabs stay open all day here, so that work adds up per open tab. The period and stagger match the old sine curve. The bounce is now a keyframe approximation of it.
- **CSS blink instead of `setInterval`** (reduces E): there is no timer per streamed message anymore. Each new cursor starts blinking visible-first, as before.
- **Bug fixed, dots never disappeared:** `.thinking { display: flex }` overrides the `hidden` attribute, so `hideThinking()` only froze the dots on screen. `.thinking[hidden] { display: none }` fixes that. Hidden elements also don't run their CSS animation.
- **Bug fixed, stuck indicator:** if `fetch` or the stream failed, the dots stayed and the rAF loop ran forever. If the stream ended with no chunks, `stopCursor(undefined)` threw. `try/finally` and `cursor?.remove()` now clean up in every case. Errors still reject `sendPrompt` as before.

`prefers-reduced-motion: reduce` turns both animations off. The dots stay visible at half opacity and the cursor stays solid. The four public functions keep their signatures.

