```nginx
server {
    listen 80;
    server_name infer.internal.example.com;

    root /srv/playground/dist;
    index index.html;

    gzip on;
    gzip_comp_level 9;
    gzip_proxied any;
    gzip_types text/css application/javascript application/json
               image/png image/jpeg application/octet-stream;

