make the output part faster, takes forever on the nas

```python
#!/usr/bin/env python3
"""dupes.py - list duplicate files under a directory by content hash."""
import argparse
import hashlib
import os
import sys
from collections import defaultdict


def file_digest(path, chunk_size=1 << 20):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            h.update(chunk)
    return h.hexdigest()


def find_dupes(root):
    groups = defaultdict(list)
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            path = os.path.join(dirpath, name)
            if os.path.islink(path):
                continue
            try:
                groups[file_digest(path)].append(path)
            except OSError as e:
                print(f"skip {path}: {e}", file=sys.stderr)
    return {d: sorted(p) for d, p in groups.items() if len(p) > 1}


def render(dupes):
    lines = []
    for digest, paths in sorted(dupes.items()):
        lines.append(f"{digest[:12]}  ({len(paths)} copies)")
        for p in paths:
            lines.append(f"    {p}")
    return "\n".join(lines)


def main(argv=None):
    parser = argparse.ArgumentParser(description="List duplicate files by content.")
    parser.add_argument("root", nargs="?", default=".")
    args = parser.parse_args(argv)
    dupes = find_dupes(args.root)
    if not dupes:
        print("no duplicates found", file=sys.stderr)
        return 1
    sys.stdout.write(render(dupes) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

