```python
def label(level):
    if level >= 50:
        return "CRIT"
    elif level >= 40 and level < 50:
        return "ERROR"
    elif level >= 30 and level < 40:
        return "WARN"
    elif level >= 20 and level < 30:
        return "INFO"
    elif level >= 0 and level < 20:
        return "DEBUG"
    return "?"


def render_report(records, job):
    out = ""
    out += "# job: " + job + "\n"
    counts = {}
    for r in records:
        tag = label(r["level"])
        counts[tag] = counts.get(tag, 0) + 1
        out += f'{r["ts"]} [{tag:<5}] {r["step"]}: {r["msg"]}\n'
    out += "--\n"
    for tag in sorted(counts):
        out += f"{tag}: {counts[tag]}\n"
    return out
```

```python
def label(level):
    if level >= 50:
        return "CRIT"
    bucket = level // 10
    if bucket == 4:
        return "ERROR"
    elif bucket == 3:
        return "WARN"
    elif bucket == 2:
        return "INFO"
    elif bucket == 0 or bucket == 1:
        return "DEBUG"
    return "?"


def render_report(records, job):
    lines = [f"# job: {job}"]
    counts = {}
    for r in records:
        tag = label(r["level"])
        counts[tag] = counts.get(tag, 0) + 1
        lines.append(f'{r["ts"]} [{tag:<5}] {r["step"]}: {r["msg"]}')
    lines.append("--")
    lines.extend(f"{tag}: {counts[tag]}" for tag in sorted(counts))
    return "\n".join(lines) + "\n"
