Hi, I am quite new to Python and wrote this check for our deploy pipeline. Before every deploy we render the helm charts for all 14 clusters (around 9000 yaml docs). This script checks that every container image comes from a registry we allow and does not use a tag like latest. It works, but the job got really slow since we added more clusters. Yesterday it also crashed on one manifest with "ValueError: not enough values to unpack". I don't really know what is wrong. Can you review it please?

```python
import sys
import yaml
from fnmatch import fnmatch
from pathlib import Path

ALLOWED = [
    "registry.internal:5000/platform/*",
    "registry.internal:5000/payments/*",
    "ghcr.io/our-org/*",
    "docker.io/library/nginx",
    "docker.io/library/redis",
    # ... about 60 more
]
BLOCKED_TAGS = {"latest", "dev", "main"}


def parse_image(ref):
    if "@" in ref:
        name, digest = ref.split("@", 1)
        return name, None, digest
    name, tag = ref.rsplit(":", 1)
    return name, tag, None


def check_image(ref):
    problems = []
    name, tag, digest = parse_image(ref)
    if "/" not in name:
        name = "docker.io/library/" + name
    if not any(fnmatch(name, pattern) for pattern in ALLOWED):
        problems.append(f"registry not allowed: {name}")
    if digest is None and tag in BLOCKED_TAGS:
        problems.append(f"mutable tag: {tag}")
    return problems


def images_in(doc):
    spec = doc.get("spec", {})
    pod = spec.get("template", {}).get("spec", spec)
    for c in pod.get("containers", []) + pod.get("initContainers", []):
        yield c["image"]


def main(root):
    failed = False
    for path in sorted(Path(root).rglob("*.yaml")):
        for doc in yaml.safe_load_all(path.read_text()):
            if not doc:
                continue
            for ref in images_in(doc):
                for problem in check_image(ref):
                    print(f"{path}: {problem}")
                    failed = True
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1]))
```

