// scripts/minify-widget.mjs
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { minify } from 'terser';

const SRC = 'widget/buy-button.js';
const OUT_DIR = 'dist';
const OUT_NAME = 'buy-button.min.js';

const code = await readFile(SRC, 'utf8');

const result = await minify({ 'buy-button.js': code }, {
  ecma: 2018,
  compress: { drop_debugger: true },
  mangle: true,
  format: { comments: 'some' }, // keeps /*! ... */ and @license comments
