    filename: OUT_NAME,
    url: `${OUT_NAME}.map`,
    includeSources: true,
  },
});

await mkdir(OUT_DIR, { recursive: true });
await writeFile(`${OUT_DIR}/${OUT_NAME}`, result.code);
await writeFile(`${OUT_DIR}/${OUT_NAME}.map`, result.map);

console.log(
  `${SRC}: ${Buffer.byteLength(code)} B -> ${Buffer.byteLength(result.code)} B`
);
