  const wanted = filter.value;
  messages.forEach((m) => {
    if (wanted !== 'all' && m.severity !== wanted) return;
    const tr = document.createElement('tr');
    const cols = [
      [m.file, 'file'],
      [m.line + ':' + m.col, 'pos'],
      [m.ruleId || '-', 'rule'],
      [m.severity, 'sev'],
      [m.message, 'msg'],
    ];
