We run this release gate in GitLab CI on every push to main, as its own job. I want to make the job lighter on CPU and energy. Requirements: same output and same exit codes, stdlib only, no new dependencies, and it must stay readable for the team. Please optimize it as you see fit. I suspect the `from os.path import *` at the top is a waste.

```python
#!/usr/bin/env python3
"""Release gate: check built artifacts before upload."""
import sys
from os import listdir, environ
from os.path import *

DIST = environ.get("DIST_DIR", "dist")
MAX_BYTES = 50 * 1024 * 1024


def read_version():
    with open(join(dirname(abspath(__file__)), "VERSION")) as f:
        return f.read().strip()


def main():
    version = read_version()
    if not isdir(DIST):
        print("missing dist dir: " + DIST)
        return 2

    problems = []
    wheels = 0
    for name in sorted(listdir(DIST)):
        path = join(DIST, name)
        if not isfile(path):
            continue
        if name.endswith(".whl"):
            wheels += 1
            if "-" + version + "-" not in name:
                problems.append(name + ": version mismatch, expected " + version)
        if getsize(path) > MAX_BYTES:
            problems.append(name + ": too large")

    if wheels == 0:
        problems.append("no wheel found")

    for p in problems:
        print(p)
    print("checked %d wheel(s), %d problem(s)" % (wheels, len(problems)))
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
```

