export function mountRejects(root, rejects, pageSize = 100) {
  const pages = Math.max(1, Math.ceil(rejects.length / pageSize));
  let page = 0;

  const prev = document.createElement('button');
  prev.type = 'button';
  prev.textContent = 'Prev';
  const next = document.createElement('button');
  next.type = 'button';
  next.textContent = 'Next';
  const label = document.createElement('span');

  const table = document.createElement('table');
  table.innerHTML =
    '<thead><tr><th>Row</th><th>Source</th><th>Reason</th><th>Raw</th></tr></thead>';
  const body = document.createElement('tbody');
  table.append(body);

  function render() {
    const start = page * pageSize;
    const frag = document.createDocumentFragment();
    for (const r of rejects.slice(start, start + pageSize)) {
      const tr = document.createElement('tr');
      for (const value of [r.rowNum, r.source, r.reason, r.raw]) {
        const td = document.createElement('td');
        td.textContent = value;
        tr.append(td);
      }
      frag.append(tr);
    }
    body.replaceChildren(frag);
    label.textContent = ` Page ${page + 1} of ${pages} (${rejects.length} rows) `;
    prev.disabled = page === 0;
    next.disabled = page === pages - 1;
  }

  prev.addEventListener('click', () => { page -= 1; render(); });
  next.addEventListener('click', () => { page += 1; render(); });

  root.replaceChildren(prev, label, next, table);
  render();
}
```

