from urllib.parse import parse_qs

SORT_COLUMNS = {
    "created": "created_at",
    "total": "total_cents",
    "status": "status",
}
MAX_LIMIT = 100


class BadRequest(Exception):
    def __init__(self, message):
        super().__init__(message)
        self.message = message


def parse_list_params(query_string):
    params = parse_qs(query_string)

    try:
        limit = int(params.get("limit", ["25"])[0])
        offset = int(params.get("offset", ["0"])[0])
    except ValueError:
        raise BadRequest("limit and offset must be integers")

    if not 1 <= limit <= MAX_LIMIT or offset < 0:
        raise BadRequest("limit or offset out of range")

    column = SORT_COLUMNS.get(params.get("sort", ["created"])[0])
    if column is None:
        raise BadRequest("unknown sort field")

    return limit, offset, column


def list_orders(db, customer_id, query_string):
    limit, offset, column = parse_list_params(query_string)
    sql = (
        "SELECT id, status, total_cents, created_at FROM orders "
        f"WHERE customer_id = ? ORDER BY {column} DESC LIMIT ? OFFSET ?"
    )
    return db.execute(sql, (customer_id, limit, offset)).fetchall()
