def normalize_unit(raw):
    cleaned = " ".join(raw.strip().lower().rstrip(".").split())
    try:
        return UNIT_ALIASES[cleaned]
    except KeyError:
        return cleaned


def clean_rows(rows):
    out = []
    for row in rows:
        out.append({
            "sku": row["sku"].strip(),
            "qty": int(row["qty"]),
            "unit": normalize_unit(row["unit"]),
        })
    return out


def clean_file(path):
    with open(path, newline="") as f:
        return clean_rows(csv.DictReader(f))
