```javascript
// build.mjs - bundles the logscope UI into dist/
import { readFile, writeFile, mkdir, copyFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';

const SRC = 'ui';
const OUT = 'dist';
const jsFiles = ['vendor/dayjs.min.js', 'api.js', 'filters.js', 'viewer.js', 'main.js'];
const cssFiles = ['vendor/bootstrap.css', 'theme.css'];

const hash = (buf) => createHash('sha256').update(buf).digest('hex').slice(0, 8);

async function concat(files) {
  const parts = [];
  for (const f of files) parts.push(await readFile(path.join(SRC, f), 'utf8'));
  return parts.join('\n');
}

async function main() {
