  const css = await concat(cssFiles);
  const jsName = `app.${hash(js)}.js`;
  const cssName = `app.${hash(css)}.css`;
  await writeFile(path.join(OUT, jsName), js);
  await writeFile(path.join(OUT, cssName), css);

