```javascript
// viewer.js
const MAX_LINES = 500;

function levelClass(level) {
  return { ERROR: 'text-danger', WARN: 'text-warning', INFO: 'text-body', DEBUG: 'text-muted' }[level] || 'text-body';
}

function renderEntries(tbody, entries) {
