from decimal import Decimal

FREE_SHIPPING_FROM = Decimal("75.00")
NON_DE_SURCHARGE = Decimal("6.00")


def shipping_fee(weight_g: int, country: str, subtotal: Decimal) -> Decimal:
    if country == "DE" and subtotal >= FREE_SHIPPING_FROM:
        return Decimal("0.00")
    if weight_g <= 500:
        fee = Decimal("3.90")
    elif weight_g <= 2000:
        fee = Decimal("5.90")
    elif weight_g <= 5000:
