```javascript
const fs = require('fs');
const readline = require('readline');

const file = process.argv[2];
if (!file) {
  console.error('usage: node count-status.js <access.log>');
  process.exit(1);
}

const counts = new Map();
let total = 0;
let skipped = 0;

const rl = readline.createInterface({ input: fs.createReadStream(file) });

rl.on('line', (line) => {
  const m = line.match(/^(\S+) \S+ \S+ \[[^\]]+\] "(\w+) (\S+)[^"]*" (\d{3}) /);
  if (!m) {
    skipped++;
