// recon-report.js - shows rows that differ between staging and warehouse after nightly load
const PAGE_SIZE = 100;
const COLUMNS = [
  ['Table', 'table'],
  ['Key', 'primaryKey'],
  ['Column', 'column'],
  ['Staging', 'stagingValue'],
  ['Warehouse', 'warehouseValue'],
];

