import csv
import re
import sys
from decimal import Decimal

DEFAULT_ZONE = "Z9"
ZONE_BY_PREFIX = {"100": "Z1", "101": "Z1", "200": "Z2", "201": "Z2", "300": "Z3"}
WEIGHT_RE = re.compile(r"^\s*([\d.,]+)\s*(kg|g|lb)\s*$", re.I)
TO_KG = {"kg": Decimal("1"), "g": Decimal("0.001"), "lb": Decimal("0.45359237")}


def parse_weight_kg(text):
    m = WEIGHT_RE.match(text)
    if not m:
        raise ValueError("bad weight: %r" % text)
    value = Decimal(m.group(1).replace(",", "."))
    return value * TO_KG[m.group(2).lower()]


def zone_for(postcode):
    try:
        return ZONE_BY_PREFIX[postcode[:3]]
    except KeyError:
        return DEFAULT_ZONE


def load_rows(f):
    for row in csv.DictReader(f):
        try:
            kg = parse_weight_kg(row["weight"])
        except ValueError:
            continue
        yield row["sku"], zone_for(row["postcode"]), kg


def main():
    per_zone = {}
    for sku, zone, kg in load_rows(sys.stdin):
        per_zone[zone] = per_zone.get(zone, Decimal("0")) + kg
    for zone in sorted(per_zone):
        print(zone, per_zone[zone])


if __name__ == "__main__":
    main()
