```python
import csv
import re


def load_rules(path):
    rules = {}
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            rules.setdefault(row["supplier_id"], []).append(
                (row["pattern"], row["replacement"])
            )
    return rules


def normalize_sku(supplier_id, sku, rules):
    for pattern, repl in rules.get(supplier_id, []):
        sku = re.sub(pattern, repl, sku)
    return sku.strip().upper()


def run(in_path, out_path, rules_path):
    rules = load_rules(rules_path)
    with open(in_path, newline="") as src, open(out_path, "w", newline="") as dst:
        reader = csv.DictReader(src)
        writer = csv.DictWriter(dst, fieldnames=["supplier_id", "sku", "qty"])
        writer.writeheader()
        for row in reader:
            row["sku"] = normalize_sku(row["supplier_id"], row["sku"], rules)
            writer.writerow(row)
```

