import os
import sys

CATEGORIES = {
    ".py": "code", ".js": "code", ".sh": "code",
    ".md": "docs", ".txt": "docs", ".rst": "docs",
    ".png": "image", ".jpg": "image", ".svg": "image",
    ".csv": "data", ".json": "data",
}

def categorize(name):
    ext = os.path.splitext(name)[1].lower()
    try:
        return CATEGORIES[ext]
    except KeyError:
        return "other"

def summarize(root):
    counts = {}
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            cat = categorize(name)
            try:
                counts[cat] += 1
            except KeyError:
                counts[cat] = 1
    return counts

def main():
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    for cat, n in sorted(summarize(root).items()):
        print(f"{cat:8} {n}")

if __name__ == "__main__":
