    listen 443 ssl http2;
    server_name data.climlab.example.org;

    ssl_certificate     /etc/ssl/climlab/fullchain.pem;
    ssl_certificate_key /etc/ssl/climlab/privkey.pem;

    root /srv/portal/www;
