import re

def load_latencies(path):
    vals = []
    with open(path) as f:
        for line in f:
            m = re.match(r'^\S+ \S+ "(?:GET|POST) (\S+) HTTP/1\.\d" (\d{3}) (\d+)ms$', line.strip())
            if m and m.group(2) != "404":
                vals.append(int(m.group(3)))
    return vals

def bucketize(latencies, width=25, max_bucket=40):
    counts = [0] * (max_bucket + 1)
    for ms in latencies:
        b = int(ms // width)
        if b > max_bucket:
            b = max_bucket
        counts[b] += 1
    return counts

def report(path):
    counts = bucketize(load_latencies(path))
    for i, c in enumerate(counts):
        if c:
            print(f"{i * 25:>4}ms+ {c}")
