Profiler says `reduce_frames` is where our nightly CCD reduction spends most of its time. Stacks are ~15 science frames of 4k×4k, one run per filter per night. Put `@njit` on it, diff only.

```python
import numpy as np


def load_stack(paths):
    frames = [np.load(p).astype(np.float32) for p in paths]
    shapes = {f.shape for f in frames}
    if len(shapes) != 1:
        raise ValueError(f"inconsistent frame shapes: {shapes}")
    return np.stack(frames)


def master_bias(bias_paths):
    return np.median(load_stack(bias_paths), axis=0)


def master_flat(flat_paths, bias):
    flats = load_stack(flat_paths) - bias
    flats /= np.median(flats, axis=(1, 2), keepdims=True)
    return np.median(flats, axis=0)


def reduce_frames(science, bias, flat, clip=5.0):
    """Bias/flat correct a science stack and sigma-clip combine it.

    science: (n, ny, nx) float32. Returns (combined image, rejected count per pixel).
    """
    sci = (science - bias) / flat
    med = np.median(sci, axis=0)
    dev = np.abs(sci - med)
    sigma = 1.4826 * np.median(dev, axis=0)
    mask = dev > clip * sigma
    sci[mask] = np.nan
    return np.nanmean(sci, axis=0), mask.sum(axis=0)
```

