const PAGE_SIZE = 100;
const EAGER_ROWS = 8; // thumbnails visible without scrolling load right away

const body = document.getElementById('stock');
const info = document.getElementById('info');
const prev = document.getElementById('prev');
const next = document.getElementById('next');

let items = [];
let view = [];
let page = 0;

function cell(text) {
  const td = document.createElement('td');
  td.textContent = text;
  return td;
}

function render() {
  const start = page * PAGE_SIZE;
  const frag = document.createDocumentFragment();
  view.slice(start, start + PAGE_SIZE).forEach((it, i) => {
    const tr = document.createElement('tr');
    if (it.qty <= it.reorder) tr.className = 'low';
    const img = document.createElement('img');
    img.src = it.thumb;
    img.alt = '';
    img.width = 48;
    img.height = 48;
    img.loading = i < EAGER_ROWS ? 'eager' : 'lazy';
    const photo = document.createElement('td');
    photo.appendChild(img);
    tr.append(photo, cell(it.sku), cell(it.name), cell(it.bin), cell(it.qty), cell(it.reorder));
    frag.appendChild(tr);
  });
  body.replaceChildren(frag);

  const pages = Math.max(1, Math.ceil(view.length / PAGE_SIZE));
  info.textContent = view.length + ' items, page ' + (page + 1) + ' of ' + pages;
  prev.disabled = page === 0;
  next.disabled = page >= pages - 1;
}

