  items = data.map(it => ({ ...it, search: (it.sku + ' ' + it.name).toLowerCase() }));
  view = items;
  render();
});

document.getElementById('q').addEventListener('input', e => {
  const t = e.target.value.toLowerCase();
  view = items.filter(it => it.search.includes(t));
  page = 0;
