        self.net = nn.Sequential(
            nn.Linear(6, 32),
            nn.ReLU(),
            nn.Linear(32, 3),
        )

    def forward(self, x):
        return self.net(x)


# Load once when the server starts, not on every request.
model = PlanNet()
model.load_state_dict(
    torch.load("models/plan_net.pt", map_location="cpu", weights_only=True)
)
model.eval()

app = Flask(__name__)


@torch.no_grad()
def recommend(values):
    x = torch.tensor([values], dtype=torch.float32) / SCALE
    probs = torch.softmax(model(x), dim=1)[0]
    best = int(probs.argmax())
    return PLANS[best], float(probs[best])


@app.post("/api/recommend-plan")
def recommend_plan():
    data = request.get_json(silent=True) or {}
    try:
        values = [float(data[name]) for name in FEATURES]
    except (KeyError, TypeError, ValueError):
        return jsonify(error=f"send numbers for: {', '.join(FEATURES)}"), 400

    plan, confidence = recommend(values)
    return jsonify(plan=plan, confidence=round(confidence, 3))


if __name__ == "__main__":
    app.run(port=8000)
```

The page can send `{"team_size": 8, "projects": 3, ...}` and gets back something like `{"plan": "team", "confidence": 0.82}`. The `SCALE` values are my guess for the input ranges. Use the same scaling your friend used in training, or the answers will be wrong.

**Green Notes**
- **No gradient tracking for inference** (reduces E): `@torch.no_grad()` on `recommend` stops PyTorch from building the autograd graph, which this endpoint never needs because it only predicts. This runs on every quiz submit, so it adds up. In Green Metrics Tool micro-benchmarks, 100,000 CPU inferences used ~157 J without `torch.no_grad()` and ~135 J with it, about 14% less.

Two more things that help correctness: the model is loaded once at startup, and `model.eval()` is called so layers behave in prediction mode. `weights_only=True` makes `torch.load` refuse to run arbitrary code from the file.

