```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Trivy report</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 1rem; }
  table { border-collapse: collapse; width: 100%; }
  th, td { border-bottom: 1px solid #ddd; padding: 4px 8px; text-align: left; }
  .CRITICAL { color: #b00020; font-weight: bold; }
  .HIGH { color: #c0392b; }
</style>
</head>
<body>
<h1>Vulnerabilities <span id="count"></span></h1>
<label>Severity
  <select id="sev">
    <option value="">all</option>
    <option>CRITICAL</option><option>HIGH</option><option>MEDIUM</option>
    <option>LOW</option><option>UNKNOWN</option>
  </select>
</label>
<input id="q" type="search" placeholder="CVE or package">
<table>
  <thead>
    <tr><th>Severity</th><th>ID</th><th>Package</th><th>Installed</th>
        <th>Fixed</th><th>Target</th><th>Title</th></tr>
  </thead>
  <tbody id="rows"></tbody>
</table>
<p>
  <button id="prev">Prev</button>
  <span id="page"></span>
  <button id="next">Next</button>
</p>
<script>
const PAGE_SIZE = 100;
const ORDER = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3, UNKNOWN: 4 };
let all = [];
let shown = [];
let page = 0;

function render() {
  const pages = Math.max(1, Math.ceil(shown.length / PAGE_SIZE));
  page = Math.min(page, pages - 1);
  const frag = document.createDocumentFragment();
  for (const v of shown.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)) {
    const tr = document.createElement('tr');
    for (const text of [v.sev, v.id, v.pkg, v.installed, v.fixed, v.target, v.title]) {
      const td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    }
    if (v.sev in ORDER) tr.firstChild.className = v.sev;
    frag.appendChild(tr);
  }
  document.getElementById('rows').replaceChildren(frag);
  document.getElementById('count').textContent = `(${shown.length} of ${all.length})`;
  document.getElementById('page').textContent = `page ${page + 1} / ${pages}`;
  document.getElementById('prev').disabled = page === 0;
  document.getElementById('next').disabled = page >= pages - 1;
}

function applyFilter() {
  const sev = document.getElementById('sev').value;
  const q = document.getElementById('q').value.trim().toLowerCase();
  shown = all.filter(v =>
    (!sev || v.sev === sev) &&
    (!q || v.id.toLowerCase().includes(q) || v.pkg.toLowerCase().includes(q)));
  page = 0;
  render();
}

document.getElementById('sev').addEventListener('change', applyFilter);
document.getElementById('q').addEventListener('input', applyFilter);
document.getElementById('prev').addEventListener('click', () => { page--; render(); });
document.getElementById('next').addEventListener('click', () => { page++; render(); });

fetch('trivy-report.json')
  .then(r => { if (!r.ok) throw new Error(r.status); return r.json(); })
  .then(report => {
    for (const res of report.Results || []) {
      for (const v of res.Vulnerabilities || []) {
        all.push({
          sev: v.Severity || 'UNKNOWN',
          id: v.VulnerabilityID || '',
          pkg: v.PkgName || '',
          installed: v.InstalledVersion || '',
          fixed: v.FixedVersion || '',
          target: res.Target || '',
          title: v.Title || '',
        });
      }
    }
    all.sort((a, b) => (ORDER[a.sev] ?? 5) - (ORDER[b.sev] ?? 5));
    applyFilter();
  })
  .catch(err => {
    document.getElementById('count').textContent = `(could not load report: ${err.message})`;
  });
</script>
</body>
</html>
