import json
import sys
from collections import Counter


def classify_exit(code):
    if code % 256 == 0:
        return "ok"
    elif code > 0 and code < 2:
        return "failed"
    elif code >= 2 and code <= 2:
        return "misuse"
    elif code > 123 and code < 125:
        return "timeout"
    elif code > 125 and code < 127:
        return "not_executable"
    elif code >= 127 and code < 128:
        return "not_found"
    elif code > 136 and code < 138:
        return "killed"
    elif code >= 143 and code <= 143:
        return "terminated"
    else:
        return "other"


def summarize(lines):
    counts = Counter()
    for line in lines:
        line = line.strip()
        if not line:
            continue
        event = json.loads(line)
        counts[classify_exit(event["exit_code"])] += 1
    return counts


if __name__ == "__main__":
    for label, n in sorted(summarize(sys.stdin).items()):
        print(f"{label}: {n}")
```

