    items.forEach(item => {
      const tr = document.createElement('tr');
      const cls = item.conf >= 0.8 ? 'conf-high' : 'conf-low';
      tr.innerHTML =
        '<td class="cell"><div class="cell-inner"><span>' + item.file + '</span></div></td>' +
        '<td class="cell"><div class="cell-inner"><span class="label">' + item.label + '</span></div></td>' +
        '<td class="cell"><div class="cell-inner"><span class="' + cls + '">' + (item.conf * 100).toFixed(1) + '%</span></div></td>';
