import csv
import math
from collections import defaultdict

MAX_BUCKET = 20  # 2**20 ms, ~17 min; anything slower lands here


def load_results(path):
    """Rows exported from the CI results DB: suite,test,duration_s,status"""
    with open(path, newline="") as f:
        for suite, test, duration_s, status in csv.reader(f):
            yield suite, test, float(duration_s) * 1000.0, status


def duration_histograms(results):
    hist = defaultdict(lambda: [0] * (MAX_BUCKET + 1))
    for suite, _test, duration_ms, status in results:
        if status == "skipped":
            continue
        bucket = int(math.log2(duration_ms))
        if bucket > MAX_BUCKET:
            bucket = MAX_BUCKET
        hist[suite][bucket] += 1
    return hist


def p95_bucket(counts):
    total = sum(counts)
    seen = 0
    for i, n in enumerate(counts):
        seen += n
        if seen >= 0.95 * total:
            return i
    return None
