import re
import sys
from collections import Counter

import numpy as np

LINE_RE = re.compile(
    r'(?P<ip>\S+) \S+ \S+ \[(?P<ts>[^\]]+)\] "(?P<method>\S+) (?P<path>\S+) [^"]*" '
    r'(?P<status>\d{3}) (?P<bytes>\d+|-) "[^"]*" "(?P<ua>[^"]*)" (?P<rt>[\d.]+)'
)

BOT_RE = re.compile(r"bot|crawl|spider|slurp|curl|python-requests|Go-http-client", re.I)
MOBILE_RE = re.compile(r"Mobile|Android|iPhone|iPad", re.I)
BROWSER_RES = [
    ("edge", re.compile(r"Edg/(\d+)")),
    ("chrome", re.compile(r"Chrome/(\d+)")),
    ("firefox", re.compile(r"Firefox/(\d+)")),
    ("safari", re.compile(r"Version/(\d+).*Safari/")),
]

# latency buckets in ms, same as our Prometheus histogram
EDGES = [5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000]


def classify_agent(ua):
    if BOT_RE.search(ua):
        return ("bot", "other", "bot")
    device = "mobile" if MOBILE_RE.search(ua) else "desktop"
    for name, rx in BROWSER_RES:
        m = rx.search(ua)
        if m:
            return (device, name, m.group(1))
    return (device, "other", "")


def bucket_counts(latencies_ms, edges):
    counts = np.zeros(len(edges) + 1, dtype=np.int64)
    for i in range(len(latencies_ms)):
        v = latencies_ms[i]
        j = 0
        while j < len(edges) and v > edges[j]:
            j += 1
        counts[j] += 1
    return counts


def summarize(path):
    agents = Counter()
    latencies = []
    with open(path, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            m = LINE_RE.match(line)
            if not m:
                continue
            device, browser, major = classify_agent(m["ua"])
            agents[(device, browser, major)] += 1
            latencies.append(float(m["rt"]) * 1000.0)
    lat = np.asarray(latencies, dtype=np.float64)
    return agents, bucket_counts(lat, np.asarray(EDGES, dtype=np.float64))


if __name__ == "__main__":
    agents, counts = summarize(sys.argv[1])
    for key, n in agents.most_common(20):
        print(*key, n, sep="\t")
    labels = [f"<= {e} ms" for e in EDGES] + [f"> {EDGES[-1]} ms"]
    for label, n in zip(labels, counts):
        print(f"{label:>12}  {n}")
