  -v msg_fields='expected 3 fields, got ' \
  -v msg_id='id is not a number' \
  -v msg_dup='duplicate id, first seen on line ' \
  -v msg_email='invalid email' \
  -v msg_role='unknown role: ' '
  BEGIN {
    n = split(role_list, r)
    for (i = 1; i <= n; i++) roles[r[i]] = 1
  }
  { sub(/\r$/, "") }                    # tolerate CRLF exports
  NR == 1 && $1 ~ /^id$/ { next }       # skip header
  /^[[:space:]]*$/ { next }             # skip blank lines
  {
    err = ""
    if (NF != 3) {
      err = msg_fields NF
    } else if ($1 !~ /^[0-9]+$/) {
      err = msg_id
    } else if ($1 in seen) {
      err = msg_dup seen[$1]
    } else {
      seen[$1] = NR
      if ($2 !~ /^[^@ ]+@[^@ ]+[.][^@ ]+$/) err = msg_email
      else if (!($3 in roles))             err = msg_role $3
    }
    if (err != "") {
      printf "line %d: %s: %s\n", NR, err, $0
      bad++
    }
  }
  END {
    if (bad) {
      printf "%d invalid line(s)\n", bad
      exit 1
    }
  }
' "$1"
