Requirements:
- Keep it CommonJS, the CI image has Node 18 and our other scripts use `require`.
- Keep the file order. The files share globals, there are no imports.
- Keep the output name `dist/app.<hash>.js` and `dist/manifest.json`, the HTML template reads the manifest.
- `esbuild` is already in our devDependencies, so use that.
- Keep the `console.*` calls, the page logs errors there on purpose.

```javascript
// scripts/build-ui.js
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const SRC = path.join(__dirname, '..', 'ui');
const OUT = path.join(__dirname, '..', 'dist');
const ORDER = ['config.js', 'api.js', 'render.js', 'main.js'];

function strip(code) {
  return code
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\/\/.*$/gm, '')
    .replace(/\n\s*\n/g, '\n');
}

fs.mkdirSync(OUT, { recursive: true });

let bundle = '';
for (const f of ORDER) {
  bundle += fs.readFileSync(path.join(SRC, f), 'utf8') + '\n';
}

const min = strip(bundle);
const hash = crypto.createHash('md5').update(min).digest('hex').slice(0, 8);
const name = `app.${hash}.js`;

fs.writeFileSync(path.join(OUT, name), min);
fs.writeFileSync(
  path.join(OUT, 'manifest.json'),
  JSON.stringify({ 'app.js': name }, null, 2)
);
console.log(`built ${name} (${min.length} bytes)`);
