const name = `app.${hash}.js`;

fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(path.join(OUT, name), min);
fs.writeFileSync(
  path.join(OUT, 'manifest.json'),
  JSON.stringify({ 'app.js': name }, null, 2)
