```js
const canvas = document.querySelector('#runner-load');
const ctx = canvas.getContext('2d');
const samples = new Array(120).fill(0);
let pending = false;

function schedule() {
  if (pending || document.hidden) return;
  pending = true;
  requestAnimationFrame(draw);
}

function draw() {
  pending = false;
  const { width, height } = canvas;
  ctx.clearRect(0, 0, width, height);
  ctx.beginPath();
  samples.forEach((cpu, i) => {
    const x = (i / (samples.length - 1)) * width;
    const y = height - (cpu / 100) * height;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.strokeStyle = '#2b8a3e';
  ctx.lineWidth = 2;
  ctx.stroke();
}

const source = new EventSource('/api/runners/load/stream');
source.onmessage = (e) => {
  samples.push(JSON.parse(e.data).cpu);
  samples.shift();
  schedule();
};

document.addEventListener('visibilitychange', () => {
  if (!document.hidden) schedule();
});
```

