PR change detector in our monorepo CI. Runs on every PR and some PRs touch 5k+ files. Diff only, please.

```python
import fnmatch
import os
import subprocess

RULES = [
    ("services/payments", "payments"),
    ("services/checkout", "checkout"),
    ("libs/*", "all-services"),
    ("infra/terraform", "infra"),
    (".github/workflows", "ci"),
    ("docs", "docs"),
]

def changed_files(base="origin/main"):
    out = subprocess.run(
        ["git", "diff", "--name-only", base + "...HEAD"],
        capture_output=True, text=True, check=True,
    ).stdout
    return out.splitlines()

def target_for_dir(directory):
    parts = directory.split("/")
    while parts:
        candidate = "/".join(parts)
        for pattern, target in RULES:
            if fnmatch.fnmatch(candidate, pattern):
                return target
        parts.pop()
    return "root"

def targets_for_changes(files):
    targets = set()
    for path in files:
        targets.add(target_for_dir(os.path.dirname(path)))
    return sorted(targets)
```

