  <tbody id="rows"></tbody>
</table>
<script id="data" type="application/json">__DATA__</script>
<script>
  const files = JSON.parse(document.getElementById('data').textContent);
  const PAGE_SIZE = 100;
  const body = document.getElementById('rows');
  const info = document.getElementById('page-info');
  const prev = document.getElementById('prev');
  const next = document.getElementById('next');
  const filter = document.getElementById('filter');
  let matches = files;
  let page = 0;

  function fmtSize(n) {
    const units = ['B', 'KB', 'MB', 'GB'];
    let i = 0;
    while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
    return n.toFixed(i ? 1 : 0) + ' ' + units[i];
  }

  function cell(text, cls) {
    const td = document.createElement('td');
    td.textContent = text;
    if (cls) td.className = cls;
    return td;
  }

  function render() {
    const start = page * PAGE_SIZE;
    const frag = document.createDocumentFragment();
    for (const f of matches.slice(start, start + PAGE_SIZE)) {
      const tr = document.createElement('tr');
      tr.append(cell(f.path), cell(fmtSize(f.size), 'size'), cell(f.hash.slice(0, 12)));
      frag.appendChild(tr);
    }
    body.replaceChildren(frag);
    info.textContent = (matches.length ? start + 1 : 0) + '–' +
      Math.min(start + PAGE_SIZE, matches.length) + ' of ' + matches.length;
    prev.disabled = page === 0;
    next.disabled = start + PAGE_SIZE >= matches.length;
  }

  filter.addEventListener('input', () => {
    const q = filter.value.trim().toLowerCase();
    matches = q ? files.filter(f => f.path.toLowerCase().includes(q)) : files;
    page = 0;
    render();
  });
  prev.addEventListener('click', () => { page--; render(); });
  next.addEventListener('click', () => { page++; render(); });

  document.getElementById('summary').textContent = files.length + ' duplicate files';
  render();
</script>
</body>
</html>
```

**Green Notes**
- **Search runs on the data, not the DOM:** filtering 10k small objects in JavaScript is cheap. Only the 100 matching rows on the current page become elements, so you keep the small DOM and get a search that covers everything.
- It is a plain substring match, case-insensitive. If you need glob or regex later, change the one `filter` line.

